"use client";

import { useFrame } from "@react-three/fiber";
import { CatmullRomCurve3, MathUtils, Vector3 } from "three";
import { useMemo, useRef } from "react";
import { chapters } from "@/lib/narrative";
import { useExperience } from "@/store/experience";

const CAMERA_POINTS = [
  [0,1.5,8.5],
  [-0.1,1.6,-8.5],
  [0.15,1.72,-20],
  [0.1,1.72,-31],
  [-0.25,1.7,-43],
  [0.2,1.7,-49.2],
  [-0.2,1.72,-55.4],
  [0.22,1.72,-61.6],
  [-0.16,1.76,-67.8],
  [0.18,1.76,-74],
  [-0.12,1.8,-80.2],
  [0,2.0,-87],
  [0,2.45,-104],
  [0,3.05,-116],
] as const;

export function CameraRig() {
  const progress=useExperience((state)=>state.progress);
  const velocity=useExperience((state)=>state.velocity);
  const setChapter=useExperience((state)=>state.setChapter);
  const smoothProgress=useRef(0);
  const look=useRef(new Vector3(0,1.55,0));

  const path=useMemo(
    ()=>new CatmullRomCurve3(
      CAMERA_POINTS.map(([x,y,z])=>new Vector3(x,y,z)),
      false,
      "catmullrom",
      0.42
    ),
    []
  );

  useFrame(({camera,pointer},delta)=>{
    smoothProgress.current=MathUtils.damp(smoothProgress.current,progress,7.8,delta);
    const t=MathUtils.clamp(smoothProgress.current,0,1);
    const position=path.getPointAt(t);
    const ahead=path.getPointAt(Math.min(1,t+0.009+Math.min(Math.abs(velocity)*0.00008,0.008)));

    const inertia=Math.min(Math.abs(velocity)*0.000035,0.07);
    camera.position.x=MathUtils.damp(camera.position.x,position.x+pointer.x*(0.11+inertia),7.8,delta);
    camera.position.y=MathUtils.damp(camera.position.y,position.y+pointer.y*0.06,7.8,delta);
    camera.position.z=MathUtils.damp(camera.position.z,position.z,9.2,delta);

    look.current.x=MathUtils.damp(look.current.x,ahead.x+pointer.x*0.14,9,delta);
    look.current.y=MathUtils.damp(look.current.y,ahead.y+pointer.y*0.07,9,delta);
    look.current.z=MathUtils.damp(look.current.z,ahead.z-2.0,10,delta);
    camera.lookAt(look.current);

    const index=Math.min(chapters.length-1,Math.round(t*(chapters.length-1)));
    setChapter(chapters[index].id);
  });

  return null;
}

