"use client";

import { Bloom, EffectComposer, Noise, Vignette } from "@react-three/postprocessing";
import { BlendFunction } from "postprocessing";
import { useExperience } from "@/store/experience";
import { QUALITY } from "@/lib/quality";

export function PostFX() {
  const quality = useExperience((state) => state.quality);
  const enabled = QUALITY[quality].postprocessing;

  if (!enabled) return null;

  return (
    <EffectComposer multisampling={quality === "ultra" ? 8 : 4}>
      <Bloom
        intensity={0.16}
        luminanceThreshold={1.05}
        luminanceSmoothing={0.35}
        mipmapBlur
      />
      <Noise opacity={0.018} blendFunction={BlendFunction.SOFT_LIGHT} />
      <Vignette eskil={false} offset={0.18} darkness={0.52} />
    </EffectComposer>
  );
}

