"use client";

import { Line, Text } from "@react-three/drei";
import { useMemo } from "react";
import { Vector3 } from "three";
import { chapters, type CapabilityId } from "@/lib/narrative";
import { useExperience } from "@/store/experience";

type Node = {
  id: CapabilityId;
  label: string;
  position: Vector3;
};

const labels: Partial<Record<CapabilityId, string>> = {
  compute: "COMPUTE",
  data: "DATA",
  software: "SOFTWARE",
  math: "MATH",
  ml: "ML",
  "responsible-ai": "RESPONSIBLE AI",
  analytics: "ANALYTICS",
  language: "LANGUAGE",
  governance: "GOVERNANCE",
  decision: "DECISION",
  knowledge: "KNOWLEDGE",
  retrieval: "RETRIEVAL",
  evaluation: "EVALUATION",
  engineering: "ENGINEERING",
  evidence: "EVIDENCE",
  operations: "OPERATIONS",
  orchestration: "ORCHESTRATION",
};

export function CapabilityGraph() {
  const activeChapter = useExperience((state) => state.chapter);

  const { nodes, edges } = useMemo(() => {
    const ordered: CapabilityId[] = [];
    chapters.forEach((chapter) => {
      chapter.capabilities.forEach((capability) => {
        if (!ordered.includes(capability)) ordered.push(capability);
      });
    });

    const nodeMap = new Map<CapabilityId, Node>();
    ordered.forEach((id, index) => {
      const ring = index < 7 ? 0 : index < 13 ? 1 : 2;
      const indexInRing = ring === 0 ? index : ring === 1 ? index - 7 : index - 13;
      const count = ring === 0 ? 7 : ring === 1 ? 6 : Math.max(1, ordered.length - 13);
      const angle = (indexInRing / count) * Math.PI * 2 + ring * 0.32;
      const radius = 1.55 + ring * 0.85;
      nodeMap.set(id, {
        id,
        label: labels[id] ?? id.toUpperCase(),
        position: new Vector3(Math.cos(angle) * radius, Math.sin(angle) * 0.5, Math.sin(angle) * radius),
      });
    });

    const edgePairs: [Node, Node][] = [];
    chapters.forEach((chapter) => {
      chapter.capabilities.forEach((capability) => {
        const target = nodeMap.get(capability);
        if (!target) return;
        chapter.linksTo.forEach((sourceId) => {
          const source = nodeMap.get(sourceId);
          if (source) edgePairs.push([source, target]);
        });
      });
    });

    return { nodes: [...nodeMap.values()], edges: edgePairs };
  }, []);

  const active = chapters.find((chapter) => chapter.id === activeChapter);
  const activeIds = new Set<CapabilityId>([...(active?.capabilities ?? []), ...(active?.linksTo ?? [])]);

  return (
    <group position={[0, 1.6, -104]}>
      {edges.map(([from, to], index) => (
        <Line
          key={`${from.id}-${to.id}-${index}`}
          points={[from.position, to.position]}
          color="#866d4c"
          transparent
          opacity={activeIds.has(from.id) || activeIds.has(to.id) ? 0.38 : 0.08}
          lineWidth={activeIds.has(from.id) || activeIds.has(to.id) ? 1.3 : 0.6}
        />
      ))}
      {nodes.map((node) => {
        const isActive = activeIds.has(node.id);
        return (
          <group key={node.id} position={node.position}>
            <mesh scale={isActive ? 1.35 : 1}>
              <sphereGeometry args={[0.055, 14, 14]} />
              <meshStandardMaterial
                color={isActive ? "#d4a15f" : "#4e4a43"}
                emissive={isActive ? "#5f3613" : "#000000"}
                emissiveIntensity={isActive ? 0.9 : 0}
              />
            </mesh>
            <Text
              position={[0.11, 0.04, 0]}
              fontSize={0.055}
              color={isActive ? "#d8cbb8" : "#5f5a52"}
              anchorX="left"
            >
              {node.label}
            </Text>
          </group>
        );
      })}
    </group>
  );
}

