import { Environment } from "@react-three/drei";
import { useExperience } from "@/store/experience";
import { assetPath } from "@/lib/asset-path";

const workshopChapters=new Set(["foundation"]);
const industryChapters=new Set(["substrate","xy","algo","cmi","pangea","fpt","validation"]);

export function ChapterEnvironment(){
  const chapter=useExperience((state)=>state.chapter);

  if(workshopChapters.has(chapter)){
    return <Environment files={assetPath("/assets/hdri/university_workshop_1k.hdr")} background={false} />;
  }

  if(industryChapters.has(chapter)){
    return <Environment files={assetPath("/assets/hdri/industrial_workshop_foundry_1k.hdr")} background={false} />;
  }

  return <Environment preset="warehouse" background={false} />;
}

